-- The simulated Data Hub warehouse for local development (npm run sim). Generated by the private
-- release/sim_fixture.py from a small sample of the real warehouse: real table definitions and shapes,
-- about 100 rows at most per table, price and value series perturbed so they are placeholders, not
-- vendor data. Regenerate rather than edit by hand.
-- Generated 2026-11-22.

CREATE TABLE wh_connections (
    connection_name text NOT NULL,
    connector_type text NOT NULL,
    credentials_ref text NOT NULL,
    owner_username text,
    origin text DEFAULT 'platform'::text NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    seed_id uuid,
    seed_class text,
    keys jsonb DEFAULT '{}'::jsonb NOT NULL,
    last_error text,
    path_prefix text
);

CREATE TABLE wh_hooks (
    hook_id text NOT NULL,
    connection_name text NOT NULL,
    key text NOT NULL,
    params jsonb DEFAULT '{}'::jsonb NOT NULL,
    output_kind text NOT NULL,
    mode text NOT NULL,
    interval_seconds integer NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    submitted_by text,
    next_run_at timestamp with time zone,
    last_run_at timestamp with time zone,
    last_status text,
    last_error text,
    last_rows integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    data_path text,
    disabled_by text
);

CREATE TABLE wh_ohlcv (
    series_id integer NOT NULL,
    ts timestamp with time zone NOT NULL,
    open double precision,
    high double precision,
    low double precision,
    close double precision,
    volume double precision
);

CREATE TABLE wh_series (
    series_id integer NOT NULL,
    hook_id text NOT NULL,
    part text DEFAULT ''::text NOT NULL,
    field text DEFAULT ''::text NOT NULL,
    store text NOT NULL,
    first_ts timestamp with time zone,
    last_ts timestamp with time zone,
    n_rows bigint DEFAULT 0 NOT NULL,
    keep_rows bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT wh_series_store_check CHECK ((store = ANY (ARRAY['ohlcv'::text, 'values'::text, 'json'::text, 'options'::text])))
);

CREATE TABLE wh_list_members (
    list_name text NOT NULL,
    member text NOT NULL,
    member_type text DEFAULT 'symbol'::text NOT NULL,
    asset_kind text DEFAULT 'stocks'::text NOT NULL,
    added_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE wh_lists (
    name text NOT NULL,
    kind text DEFAULT 'manual'::text NOT NULL,
    category text,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    record boolean DEFAULT true NOT NULL,
    provider text,
    description text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE wh_options (
    series_id integer NOT NULL,
    ts timestamp with time zone NOT NULL,
    expiry date NOT NULL,
    side character(1) NOT NULL,
    strike real NOT NULL,
    last real,
    bid real,
    ask real,
    volume real,
    open_interest real,
    iv real,
    spot real
);

CREATE TABLE wh_process_control (
    id bigint NOT NULL,
    machine_name text NOT NULL,
    process_name text NOT NULL,
    command text NOT NULL,
    args jsonb DEFAULT '{}'::jsonb NOT NULL,
    requested_by text,
    status text DEFAULT 'pending'::text NOT NULL,
    result jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    claimed_at timestamp with time zone,
    completed_at timestamp with time zone
);

CREATE SEQUENCE wh_process_control_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE wh_process_control_id_seq OWNED BY wh_process_control.id;

CREATE TABLE wh_process_state (
    machine_name text NOT NULL,
    process_name text NOT NULL,
    pid integer,
    started_at timestamp with time zone,
    last_tick_at timestamp with time zone,
    status text DEFAULT 'running'::text NOT NULL,
    paused boolean DEFAULT false NOT NULL,
    tick_count bigint DEFAULT 0 NOT NULL,
    summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    last_error text
);

CREATE TABLE wh_records (
    hook_id text NOT NULL,
    part text DEFAULT ''::text NOT NULL,
    run_key text DEFAULT ''::text NOT NULL,
    idx text NOT NULL,
    idx_time timestamp with time zone,
    data jsonb NOT NULL,
    fetched_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE wh_seed_uploads (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_username text NOT NULL,
    seed_name text NOT NULL,
    description text,
    bundle bytea NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    reject_reason text,
    seed_id uuid,
    submitted_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    processed_at timestamp with time zone
);

CREATE TABLE wh_seeds (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_username text NOT NULL,
    seed_name text NOT NULL,
    version integer NOT NULL,
    description text,
    header jsonb DEFAULT '{}'::jsonb NOT NULL,
    bundle bytea NOT NULL,
    bundle_hash text NOT NULL,
    source_hash text,
    size_bytes bigint NOT NULL,
    origin text NOT NULL,
    deleted boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE SEQUENCE wh_series_series_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE wh_series_series_id_seq OWNED BY wh_series.series_id;

CREATE TABLE wh_values (
    series_id integer NOT NULL,
    ts timestamp with time zone NOT NULL,
    value double precision
);

CREATE VIEW wh_series_values AS
 SELECT h.connection_name,
    h.key,
    h.params,
    s.part,
    s.field,
    v.ts,
    v.value,
    s.series_id
   FROM ((wh_values v
     JOIN wh_series s USING (series_id))
     JOIN wh_hooks h ON ((h.hook_id = s.hook_id)));

CREATE TABLE wh_source_errors (
    id bigint NOT NULL,
    at timestamp with time zone DEFAULT now() NOT NULL,
    connection_name text,
    hook_id text,
    stage text NOT NULL,
    data_path text,
    problem text NOT NULL
);

CREATE SEQUENCE wh_source_errors_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE wh_source_errors_id_seq OWNED BY wh_source_errors.id;

CREATE TABLE wh_watchlist (
    symbol text NOT NULL,
    sources text[] DEFAULT '{}'::text[] NOT NULL,
    kind text DEFAULT 'stocks'::text NOT NULL,
    added_by text,
    added_at timestamp with time zone DEFAULT now() NOT NULL,
    stage text DEFAULT 'queued'::text NOT NULL,
    note text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

ALTER TABLE ONLY wh_process_control ALTER COLUMN id SET DEFAULT nextval('wh_process_control_id_seq'::regclass);

ALTER TABLE ONLY wh_series ALTER COLUMN series_id SET DEFAULT nextval('wh_series_series_id_seq'::regclass);

ALTER TABLE ONLY wh_source_errors ALTER COLUMN id SET DEFAULT nextval('wh_source_errors_id_seq'::regclass);

ALTER TABLE ONLY wh_connections
    ADD CONSTRAINT wh_connections_pkey PRIMARY KEY (connection_name);

ALTER TABLE ONLY wh_hooks
    ADD CONSTRAINT wh_hooks_connection_name_key_params_key UNIQUE (connection_name, key, params);

ALTER TABLE ONLY wh_hooks
    ADD CONSTRAINT wh_hooks_pkey PRIMARY KEY (hook_id);

ALTER TABLE ONLY wh_list_members
    ADD CONSTRAINT wh_list_members_pkey PRIMARY KEY (list_name, member);

ALTER TABLE ONLY wh_lists
    ADD CONSTRAINT wh_lists_pkey PRIMARY KEY (name);

ALTER TABLE ONLY wh_ohlcv
    ADD CONSTRAINT wh_ohlcv_pkey PRIMARY KEY (series_id, ts);

ALTER TABLE ONLY wh_options
    ADD CONSTRAINT wh_options_pkey PRIMARY KEY (series_id, ts, expiry, side, strike);

ALTER TABLE ONLY wh_process_control
    ADD CONSTRAINT wh_process_control_pkey PRIMARY KEY (id);

ALTER TABLE ONLY wh_process_state
    ADD CONSTRAINT wh_process_state_pkey PRIMARY KEY (machine_name, process_name);

ALTER TABLE ONLY wh_records
    ADD CONSTRAINT wh_records_pkey PRIMARY KEY (hook_id, part, run_key, idx);

ALTER TABLE ONLY wh_seed_uploads
    ADD CONSTRAINT wh_seed_uploads_pkey PRIMARY KEY (id);

ALTER TABLE ONLY wh_seeds
    ADD CONSTRAINT wh_seeds_owner_username_seed_name_bundle_hash_key UNIQUE (owner_username, seed_name, bundle_hash);

ALTER TABLE ONLY wh_seeds
    ADD CONSTRAINT wh_seeds_owner_username_seed_name_version_key UNIQUE (owner_username, seed_name, version);

ALTER TABLE ONLY wh_seeds
    ADD CONSTRAINT wh_seeds_pkey PRIMARY KEY (id);

ALTER TABLE ONLY wh_series
    ADD CONSTRAINT wh_series_hook_id_part_field_store_key UNIQUE (hook_id, part, field, store);

ALTER TABLE ONLY wh_series
    ADD CONSTRAINT wh_series_pkey PRIMARY KEY (series_id);

ALTER TABLE ONLY wh_source_errors
    ADD CONSTRAINT wh_source_errors_pkey PRIMARY KEY (id);

ALTER TABLE ONLY wh_values
    ADD CONSTRAINT wh_values_pkey PRIMARY KEY (series_id, ts);

ALTER TABLE ONLY wh_watchlist
    ADD CONSTRAINT wh_watchlist_pkey PRIMARY KEY (symbol);

CREATE UNIQUE INDEX wh_hooks_data_path_uq ON wh_hooks USING btree (data_path) WHERE (data_path IS NOT NULL);

CREATE INDEX wh_hooks_due_idx ON wh_hooks USING btree (enabled, next_run_at);

CREATE INDEX wh_process_control_pending_idx ON wh_process_control USING btree (machine_name, process_name, status, created_at);

CREATE INDEX wh_records_time_idx ON wh_records USING btree (hook_id, part, idx_time);

CREATE INDEX wh_seed_uploads_pending_idx ON wh_seed_uploads USING btree (status, created_at);

CREATE INDEX wh_source_errors_at_idx ON wh_source_errors USING btree (at DESC);

ALTER TABLE ONLY wh_hooks
    ADD CONSTRAINT wh_hooks_connection_name_fkey FOREIGN KEY (connection_name) REFERENCES wh_connections(connection_name);

ALTER TABLE ONLY wh_list_members
    ADD CONSTRAINT wh_list_members_list_name_fkey FOREIGN KEY (list_name) REFERENCES wh_lists(name) ON DELETE CASCADE;

ALTER TABLE ONLY wh_ohlcv
    ADD CONSTRAINT wh_ohlcv_series_id_fkey FOREIGN KEY (series_id) REFERENCES wh_series(series_id) ON DELETE CASCADE;

ALTER TABLE ONLY wh_options
    ADD CONSTRAINT wh_options_series_id_fkey FOREIGN KEY (series_id) REFERENCES wh_series(series_id) ON DELETE CASCADE;

ALTER TABLE ONLY wh_records
    ADD CONSTRAINT wh_records_hook_id_fkey FOREIGN KEY (hook_id) REFERENCES wh_hooks(hook_id) ON DELETE CASCADE;

ALTER TABLE ONLY wh_seed_uploads
    ADD CONSTRAINT wh_seed_uploads_seed_id_fkey FOREIGN KEY (seed_id) REFERENCES wh_seeds(id) ON DELETE SET NULL;

ALTER TABLE ONLY wh_series
    ADD CONSTRAINT wh_series_hook_id_fkey FOREIGN KEY (hook_id) REFERENCES wh_hooks(hook_id) ON DELETE CASCADE;

ALTER TABLE ONLY wh_values
    ADD CONSTRAINT wh_values_series_id_fkey FOREIGN KEY (series_id) REFERENCES wh_series(series_id) ON DELETE CASCADE;

