INSERT INTO wh_connections (connection_name, connector_type, credentials_ref, owner_username, origin, enabled, created_at, updated_at, seed_id, seed_class, keys, last_error, path_prefix) VALUES
  ('cftc_cot', 'cftc', 'sim:cftc_cot', NULL, 'platform', true, '2026-10-05T00:06:10.034025+00:00', '2026-11-23T02:14:22.415135+00:00', NULL, NULL, '{"positions": {"path": "positioning/cot/{market_code}", "params": {"market_code": "str"}, "description": "Weekly COT positions (open interest, non-commercial/commercial/non-reportable long & short).", "incremental": true, "output_kind": "frame"}}'::jsonb, NULL, NULL),
  ('oanda_practice', 'oanda', 'sim:oanda_practice', NULL, 'platform', true, '2026-10-03T18:14:04.418225+00:00', '2026-11-23T02:14:22.293806+00:00', NULL, NULL, '{"candles": {"path": "fx/{instrument}/{data_rate}", "params": {"data_rate": "str", "instrument": "str"}, "description": "Completed mid OHLCV bars, UTC-indexed.", "incremental": true, "output_kind": "frame"}, "orderbook": {"path": "fx/{instrument}/orderbook", "params": {"instrument": "str"}, "description": "Order book snapshots: % of open orders per price bucket (long, short).", "incremental": true, "output_kind": "frame"}, "positionbook": {"path": "fx/{instrument}/positionbook", "params": {"instrument": "str"}, "description": "Position book snapshots: % of open positions per price bucket (long, short).", "incremental": true, "output_kind": "frame"}}'::jsonb, NULL, NULL),
  ('yahoo', 'yahoo', 'sim:yahoo', NULL, 'platform', true, '2026-10-05T00:06:10.004831+00:00', '2026-11-23T02:14:22.384186+00:00', NULL, NULL, '{"fx.candles": {"path": "yahoo_fx/{instrument}/{data_rate}", "params": {"data_rate": "str", "instrument": "str"}, "description": "Completed OHLC bars (D, W or M) of a currency pair named like OANDA (EUR_USD), UTC.", "incremental": true, "output_kind": "frame"}, "etfs.candles": {"path": "equity/{instrument}/{data_rate}", "params": {"data_rate": "str", "instrument": "str"}, "description": "Completed adjusted OHLCV bars (D, W or M) of an ETF (SPY, QQQ, GLD, ...), UTC.", "incremental": true, "output_kind": "frame"}, "options.chain": {"path": "options/{ticker}/{expiries}", "params": {"ticker": "str", "expiries": "int/str"}, "description": "Snapshot of the option chain for the nearest N expiries (or \"all\"): spot, then calls / puts per expiry date, every strike.", "incremental": false, "output_kind": "frames"}, "crypto.candles": {"path": "crypto/{instrument}/{data_rate}", "params": {"data_rate": "str", "instrument": "str"}, "description": "Completed OHLCV bars (D, W or M) of a coin in a currency (BTC-USD, ETH-USD), UTC.", "incremental": true, "output_kind": "frame"}, "stocks.candles": {"path": "equity/{instrument}/{data_rate}", "params": {"data_rate": "str", "instrument": "str"}, "description": "Completed split- and dividend-adjusted OHLCV bars (D, W or M) of a stock, UTC.", "incremental": true, "output_kind": "frame"}, "breadth.above_ma": {"path": "breadth/{index}/above_{weeks}w", "params": {"index": "str", "weeks": "int"}, "description": "Share (%) of an index fund members above their N-week average (weekly).", "incremental": false, "output_kind": "frame"}, "stocks.valuation": {"path": "valuation/{ticker}", "params": {"ticker": "str"}, "description": "Daily snapshot of key valuation ratios.", "incremental": false, "output_kind": "frame"}, "stocks.fundamentals": {"path": "fundamentals/{ticker}", "params": {"ticker": "str"}, "description": "Quarterly income, balance sheet and cash flow.", "incremental": false, "output_kind": "frames"}}'::jsonb, NULL, NULL),
  ('fred', 'fred', 'sim:fred', NULL, 'platform', true, '2026-10-20T04:57:08.924301+00:00', '2026-11-23T02:14:22.324698+00:00', NULL, NULL, '{"latest": {"path": "macro/fred_latest/{series_id}", "params": {"series_id": "str"}, "description": "One FRED series as FRED publishes it now (revised values), by observation date, the way the Discord hub and FRED''s own charts read it. Revisions overwrite the stored values.", "incremental": false, "output_kind": "frame"}, "series": {"path": "macro/fred/{series_id}", "params": {"series_id": "str"}, "description": "One FRED series, first-release values indexed by publication time.", "incremental": false, "output_kind": "frame"}, "revisions": {"path": "macro/fred_revisions/{series_id}", "params": {"series_id": "str"}, "description": "Every published value of a FRED series (ALFRED vintages): the first release and each revision of each period, stamped when it was published; nothing is overwritten.", "incremental": false, "output_kind": "frame"}}'::jsonb, NULL, NULL),
  ('sec_edgar', 'edgar', 'sim:sec_edgar', NULL, 'platform', true, '2026-10-05T00:23:37.320504+00:00', '2026-11-23T02:14:22.356403+00:00', NULL, NULL, '{"facts": {"path": "filings/{ticker}", "params": {"ticker": "str", "concepts": "list"}, "description": "Reported XBRL facts per concept: quarterly and annual values, by filing time.", "incremental": false, "output_kind": "frames"}, "latest": {"path": "filing_events/_latest", "params": {"forms": "list"}, "description": "New filings market-wide from EDGAR''s latest-filings feed, minutes after release: form, company, tickers, items and events; press releases go to the articles.", "incremental": true, "output_kind": "frame"}, "filings": {"path": "filing_events/{ticker}", "params": {"ticker": "str"}, "description": "Every filing with its events (M&A, earnings, dividends, legal, insider trades, large holders).", "incremental": true, "output_kind": "frame"}, "reports": {"path": "reports/{ticker}", "params": {"ticker": "str"}, "description": "Every report by type (10-K, 10-Q, 8-K and the rest), each type its own dated text series.", "incremental": true, "output_kind": "frames"}}'::jsonb, NULL, NULL),
  ('datahub', 'databot', 'sim:datahub', NULL, 'platform', true, '2026-11-16T20:41:24.437139+00:00', '2026-11-23T02:14:22.635015+00:00', NULL, NULL, '{"stats": {"path": "stats/{ticker}", "params": {"ticker": "str"}, "description": "Calculated stock statistics from the warehouse: stub (LTM) financials and balance-sheet ratios per filing; daily E/P, P/B, EV, beta, CAPM, WACC and DCF value.", "incremental": false, "output_kind": "frames"}, "filings": {"path": "filing_ticks/{ticker}", "params": {"ticker": "str"}, "description": "Tick series of the stock''s filings from the warehouse''s EDGAR filings: 8-K items and events, Form 4 insider trades (shares, value, role) and 13D large-holder filings, at acceptance time.", "incremental": true, "output_kind": "frames"}}'::jsonb, NULL, NULL),
  ('cboe', 'cboe', 'sim:cboe', NULL, 'platform', true, '2026-11-08T02:46:40.581379+00:00', '2026-11-23T02:14:22.445008+00:00', NULL, NULL, '{"putcall": {"path": "sentiment/putcall/{ratio}", "params": {"ratio": "str"}, "description": "Cboe daily put/call ratio (total, equity, index, etp or vix), stamped after the close.", "incremental": true, "output_kind": "frame"}}'::jsonb, NULL, NULL),
  ('holdings', 'holdings', 'sim:holdings', NULL, 'platform', true, '2026-10-19T23:39:40.036308+00:00', '2026-11-23T02:14:22.474583+00:00', NULL, NULL, '{"sec.holdings": {"path": "holdings/{fund}", "params": {"fund": "str"}, "description": "Quarter-end holdings from SEC N-PORT filings (any registered fund, e.g. IWO); ~60 days late.", "incremental": false, "output_kind": "frame"}, "ssga.holdings": {"path": "holdings/{fund}", "params": {"fund": "str"}, "description": "State Street SPDR holdings (daily xlsx): SPY, DIA and the Select Sector SPDRs.", "incremental": false, "output_kind": "frame"}, "nasdaq.holdings": {"path": "holdings/{fund}", "params": {"fund": "str"}, "description": "Nasdaq-100 members for QQQ (the fund holds the index); equal weights are not given.", "incremental": false, "output_kind": "frame"}, "vanguard.holdings": {"path": "holdings/{fund}", "params": {"fund": "str"}, "description": "Vanguard ETF stock holdings (month end): VUG, VTV, VOO, ...", "incremental": false, "output_kind": "frame"}}'::jsonb, NULL, NULL),
  ('webull_stocks', 'webull', 'sim:webull_stocks', NULL, 'platform', true, '2026-10-19T23:53:03.106117+00:00', '2026-11-23T02:14:22.607778+00:00', NULL, NULL, '{"etfs.candles": {"path": "equity/{instrument}/{data_rate}", "params": {"data_rate": "str", "instrument": "str"}, "description": "Completed OHLCV bars of a US ETF, UTC (needs the Stock Quotes subscription).", "incremental": true, "output_kind": "frame"}, "crypto.candles": {"path": "crypto/{instrument}/{data_rate}", "params": {"data_rate": "str", "instrument": "str"}, "description": "Completed OHLCV bars of a coin quoted in USD (BTCUSD, ETHUSD), UTC.", "incremental": true, "output_kind": "frame"}, "stocks.candles": {"path": "equity/{instrument}/{data_rate}", "params": {"data_rate": "str", "instrument": "str"}, "description": "Completed OHLCV bars of a US stock, UTC (needs the Stock Quotes subscription).", "incremental": true, "output_kind": "frame"}, "options.contracts": {"path": "options/{ticker}/contracts", "params": {"ticker": "str"}, "description": "Listed option contracts per expiry: strike, type, multiplier (record mode keeps one snapshot per run).", "incremental": false, "output_kind": "frames"}}'::jsonb, NULL, 'webull');
